const img_Minute_Aod_s3o4 = [
  A('font_5_0.png'),
  A('font_5_1.png'),
  A('font_5_2.png'),
  A('font_5_3.png'),
  A('font_5_4.png'),
  A('font_5_5.png'),
  A('font_5_6.png'),
  A('font_5_7.png'),
  A('font_5_8.png'),
  A('font_5_9.png'),
]

const img_Weekday_o5ey = [
  A('week_w1.png'),
  A('week_w2.png'),
  A('week_w3.png'),
  A('week_w4.png'),
  A('week_w5.png'),
  A('week_w6.png'),
  A('week_w7.png'),
]

const img_Day_g6ep = [
  A('font_6_0.png'),
  A('font_6_1.png'),
  A('font_6_2.png'),
  A('font_6_3.png'),
  A('font_6_4.png'),
  A('font_6_5.png'),
  A('font_6_6.png'),
  A('font_6_7.png'),
  A('font_6_8.png'),
  A('font_6_9.png'),
]

const img_Temperature_h4f9 = [
  A('font_1_0.png'),
  A('font_1_1.png'),
  A('font_1_2.png'),
  A('font_1_3.png'),
  A('font_1_4.png'),
  A('font_1_5.png'),
  A('font_1_6.png'),
  A('font_1_7.png'),
  A('font_1_8.png'),
  A('font_1_9.png'),
]

WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    try { if (typeof hmFS !== 'undefined') variantIdx = Number(hmFS.SysProGetInt('dialcraft_variant')) || 0 } catch (e) {}

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Beer (IMG)
    const variants_0 = [A('beer_0.png'), A('beer_1.png'), A('beer_2.png'), A('beer_3.png'), A('beer_4.png'), A('beer_5.png'), A('beer_6.png'), A('beer_7.png'), A('beer_8.png'), A('beer_9.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.beer = variant_0
    F.beer = variants_0

    // Cover (IMG)
    W.cover = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(-410),
      src: A('cover.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(35),
      hour_startY: px(140),
      hour_zero: 1,
      hour_space: px(-20),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Main_74rq,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Colon Main (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(172),
      y: px(157),
      src: A('symbol_u003a.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(204),
      minute_startY: px(140),
      minute_zero: 1,
      minute_space: px(-20),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Main_772d,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(60),
      hour_startY: px(90),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Aod_s3sr,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Minute Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(60),
      minute_startY: px(230),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Aod_s3o4,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(122),
      y: px(32),
      week_en: img_Weekday_o5ey,
      week_sc: img_Weekday_o5ey,
      week_tc: img_Weekday_o5ey,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(194),
      day_startY: px(32),
      day_zero: 0,
      day_space: px(-24),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_g6ep,
      day_sc_array: img_Day_g6ep,
      day_tc_array: img_Day_g6ep,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Temperature (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(143),
      y: px(366),
      type: ui.data_type.WEATHER_CURRENT,
      font_array: img_Temperature_h4f9,
      h_space: px(-23),
      align_h: ui.align.LEFT,
      unit_en: A('degree.png'),
      unit_sc: A('degree.png'),
      unit_tc: A('degree.png'),
      negative_image: A('negative.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Glass (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('glass_front.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length)
      try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt('dialcraft_variant', variantIdx) } catch (e) {}
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
    }

    // ---- user code (project.userCode) ----
    {
      const MS = 100, TOP_EMPTY = 450, TOP_FULL = 40
      const NB = F.beer.length
      let n = 0, id = null, via = '', y = null, lastSec = -1, sub = 0, clock = null
      try { clock = new DCTime() } catch (e) {}
      // seconds of the minute from the Zepp Time sensor (else Date, else our own count)
      const seconds = () => {
        try { if (clock) { const s = clock.getSeconds(); if (typeof s === 'number' && s >= 0) return s } } catch (e) {}
        try { const s = new Date().getSeconds(); if (typeof s === 'number' && s >= 0) return s } catch (e) {}
        return Math.floor(n * MS / 1000) % 60
      }
      // the sensor only counts whole seconds, so the ticks since the second changed fill in the fraction
      const fraction = () => {
        const s = seconds()
        if (s !== lastSec) { lastSec = s; sub = 0 } else sub++
        return (s + Math.min(0.95, sub * MS / 1000)) / 60
      }
      const tick = () => {
        n++
        const ny = Math.round(TOP_EMPTY - (TOP_EMPTY - TOP_FULL) * fraction()) - TOP_EMPTY
        if (ny !== y) { y = ny; W.cover.setProperty(ui.prop.MORE, { x: 0, y: px(y) }) }
        W.beer.setProperty(ui.prop.SRC, F.beer[n % NB])
      }
      const stop = () => {
        if (id === null) return
        try { if (via === 't') timer.stopTimer(id); else clearInterval(id) } catch (e) {}
        id = null
      }
      const safe = () => { try { tick() } catch (e) {} }
      const start = () => {
        if (id !== null) return
        try {
          if (typeof timer !== 'undefined' && timer && timer.createTimer) { id = timer.createTimer(0, MS, safe); via = 't' }
          else if (typeof setInterval === 'function') { id = setInterval(safe, MS); via = 'i' }
        } catch (e) {}
      }
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: () => { lastSec = -1; start() }, pause_call: stop })
      safe()
      start()
    }
  },

  build() {
    this.initView()
  },
})
